import { useId } from "react";

import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { CheckIcon, MinusIcon } from "lucide-react";

const items = [
	{ value: "1", label: "Light", image: "/ui-light.png" },
	{ value: "2", label: "Dark", image: "/ui-dark.png" },
	{ value: "3", label: "System", image: "/ui-system.png" },
];

export default function Component() {
	const id = useId();
	return (
		<fieldset className="space-y-4">
			<legend className="text-foreground text-sm leading-none font-medium">
				Choose a theme
			</legend>
			<RadioGroup className="flex gap-3" defaultValue="1">
				{items.map((item) => (
					<label key={`${id}-${item.value}`}>
						<RadioGroupItem
							id={`${id}-${item.value}`}
							value={item.value}
							className="peer sr-only after:absolute after:inset-0"
						/>
						<img
							src={item.image}
							alt={item.label}
							width={88}
							height={70}
							className="border-input peer-focus-visible:ring-ring/50 peer-data-[state=checked]:border-ring peer-data-[state=checked]:bg-accent relative cursor-pointer overflow-hidden rounded-md border shadow-2xs transition-[color,box-shadow] outline-hidden peer-focus-visible:ring-[3px] peer-data-disabled:cursor-not-allowed peer-data-disabled:opacity-50"
						/>
						<span className="group peer-data-[state=unchecked]:text-muted-foreground/70 mt-2 flex items-center gap-1">
							<CheckIcon
								size={16}
								className="group-peer-data-[state=unchecked]:hidden"
								aria-hidden="true"
							/>
							<MinusIcon
								size={16}
								className="group-peer-data-[state=checked]:hidden"
								aria-hidden="true"
							/>
							<span className="text-xs font-medium">{item.label}</span>
						</span>
					</label>
				))}
			</RadioGroup>
		</fieldset>
	);
}

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as RadioGroupPrimitive from "@radix-ui/react-radio-group";
import { Circle } from "lucide-react";

const RadioGroup = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Root>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Root
			className={cn("grid gap-2", className)}
			{...props}
			ref={ref}
		/>
	);
});
RadioGroup.displayName = RadioGroupPrimitive.Root.displayName;

const RadioGroupItem = React.forwardRef<
	React.ElementRef<typeof RadioGroupPrimitive.Item>,
	React.ComponentPropsWithoutRef<typeof RadioGroupPrimitive.Item>
>(({ className, ...props }, ref) => {
	return (
		<RadioGroupPrimitive.Item
			ref={ref}
			className={cn(
				"aspect-square h-4 w-4 rounded-full border border-primary text-primary ring-offset-background focus:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
				className
			)}
			{...props}
		>
			<RadioGroupPrimitive.Indicator className="flex items-center justify-center">
				<Circle className="h-2.5 w-2.5 fill-current text-current" />
			</RadioGroupPrimitive.Indicator>
		</RadioGroupPrimitive.Item>
	);
});
RadioGroupItem.displayName = RadioGroupPrimitive.Item.displayName;

export { RadioGroup, RadioGroupItem };
